<?php require __DIR__.'/../inc/bootstrap.php'; require_admin(); $posts=load_json('posts.json',[]); $id=$_GET['id']??''; $editing=null; foreach($posts as $p){if((string)$p['id']===(string)$id){$editing=$p;break;}} if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??'');$content=trim($_POST['content']??'');if($title===''||$content==='')die('INPUT REQUIRED'); if($editing){foreach($posts as &$p){if((string)$p['id']===(string)$editing['id']){$p['title']=$title;$p['content']=$content;}}unset($p);}else{$posts[]=['id'=>time().random_int(100,999),'title'=>$title,'content'=>$content,'date'=>date('Y-m-d')];}save_json('posts.json',$posts);header('Location: posts.php');exit;} ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EDIT LOG</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="card"><h1>[ <?= $editing?'EDIT':'NEW' ?> LOG ]</h1><form method="post"><input name="title" value="<?=e($editing['title']??'')?>" placeholder="TITLE"><textarea name="content" placeholder="CONTENT"><?=e($editing['content']??'')?></textarea><button>SAVE</button></form><p><a href="posts.php">BACK</a></p></div></main></body></html>
